<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useCreateTemplate } from '@/api/queries/domainQueries'
import LcButton from '@/components/ui/LcButton.vue'; import LcCard from '@/components/ui/LcCard.vue'; import LcInput from '@/components/ui/LcInput.vue'; import LcSelect from '@/components/ui/LcSelect.vue'; import LcTextarea from '@/components/ui/LcTextarea.vue'
const router = useRouter(); const createTemplate = useCreateTemplate(); const form = reactive({ name: '', description: '', fieldKey: 'mood', fieldLabel: 'Mood', fieldType: 'TEXT' as 'TEXT' | 'NUMBER' | 'SCALE' }); const error = ref('')
const submit = async () => { if (!form.name || !form.fieldKey || !form.fieldLabel) { error.value = 'Template name and field definition are required.'; return } await createTemplate.mutateAsync({ name: form.name, description: form.description, fields: [{ key: form.fieldKey, label: form.fieldLabel, type: form.fieldType, isRequired: true, order: 0, moduleConfig: {} }] }); await router.push('/reports/templates') }
</script>
<template><section class="grid gap-6"><div class="overflow-hidden rounded-2xl border border-border bg-surface shadow-card"><div class="border-b border-border bg-gradient-to-br from-surface via-canvas to-surfaceMuted p-6"><p class="font-display text-xs font-bold uppercase tracking-[0.28em] text-contextDark">Reports</p><h1 class="mt-3 font-display text-3xl font-bold text-ink">Template builder</h1><p class="mt-2 max-w-3xl text-sm leading-6 text-textMuted">Define the questions that help you understand trainee recovery, progress, and readiness.</p></div></div><LcCard><form class="grid gap-4" @submit.prevent="submit"><LcInput v-model="form.name" label="Template name" required/><LcTextarea v-model="form.description" label="Description"/><div class="grid gap-4 md:grid-cols-3"><LcInput v-model="form.fieldKey" label="Field key"/><LcInput v-model="form.fieldLabel" label="Field label"/><LcSelect v-model="form.fieldType" label="Field type" :options="[{ label: 'Text', value: 'TEXT' }, { label: 'Number', value: 'NUMBER' }, { label: 'Scale', value: 'SCALE' }]"/></div><p class="text-sm text-textMuted">Keep questions short and specific so trainee answers are easy to review.</p><p v-if="error" class="text-sm text-danger">{{ error }}</p><LcButton type="submit" :loading="createTemplate.isPending.value">Save template</LcButton></form></LcCard></section></template>
